<script setup lang="ts">
import { bangkok, type Notification, type Page } from '~/utils/types'
const { admin } = useSession(); const api=useApi(); const jobs=ref<Notification[]>([]); const cursor=ref<string|null>(); const error=ref<unknown>(); const loading=ref(false); const saving=ref(false); const status=ref(''); const reason=ref(''); const selected=ref<Notification|null>(null); const message=ref('')
async function load(more=false) { if (!admin.value) return; loading.value=true; error.value=undefined; try { const query=new URLSearchParams({limit:'100'}); if(status.value) query.set('status',status.value); if(more && cursor.value) query.set('cursor',cursor.value); const page=await api.get<Page<Notification>>(`/admin/login-notifications?${query}`); jobs.value=more?[...jobs.value,...page.items]:page.items; cursor.value=page.next_cursor }catch(e){error.value=e}finally{loading.value=false} }
async function retry(){if(!selected.value)return;saving.value=true;error.value=undefined;try{await api.command(`/admin/login-notifications/${selected.value.id}/retry`,{expected_version:selected.value.version,reason:reason.value.trim()});selected.value=null;reason.value='';message.value='เข้าคิวงานเดิมเพื่อลองส่งอีกครั้งแล้ว';await load()}catch(e){error.value=e}finally{saving.value=false}}
onMounted(()=>load())
</script>
<template><div class="page-head"><div><h1>อีเมลแจ้งเตือนเข้าสู่ระบบ</h1><p>ตรวจสถานะการส่งให้เจ้าของบัญชี การรับจากผู้ให้บริการยังไม่ยืนยันว่าเข้ากล่องจดหมายแล้ว</p></div></div><Feedback v-if="!admin" :error="new Error('เฉพาะผู้ดูแลส่วนกลางเท่านั้น')" /><template v-else><Feedback :error="error" :message="message" /><section class="panel"><form class="actions" @submit.prevent="load()"><div class="field"><label for="mail-status">สถานะงาน</label><select id="mail-status" v-model="status"><option value="">ทุกสถานะ</option><option value="PENDING">รอส่ง</option><option value="PROCESSING">กำลังส่ง</option><option value="RETRY_WAIT">รอลองใหม่</option><option value="ACCEPTED_BY_PROVIDER">ผู้ให้บริการรับแล้ว</option><option value="FAILED">ส่งไม่สำเร็จ</option></select></div><button class="button" :disabled="loading">โหลดล่าสุด</button></form><UProgress v-if="loading" /><div v-if="!jobs.length && !loading" class="empty">ยังไม่มีงานแจ้งเตือนในตัวกรองนี้</div><div class="table-wrap"><table v-if="jobs.length"><thead><tr><th>ผู้รับ</th><th>สถานะ</th><th>จำนวนครั้ง / เวลาลองใหม่</th><th>จัดการ</th></tr></thead><tbody><tr v-for="job in jobs" :key="job.id"><td class="break">{{job.recipient}}<small v-if="job.last_error_code" class="muted">{{job.last_error_code}}</small></td><td><StatusTag :value="job.status" /></td><td>{{job.attempt_count}} ครั้ง<p v-if="job.next_retry_at" class="hint">{{bangkok(job.next_retry_at)}}</p></td><td><button v-if="['FAILED','RETRY_WAIT'].includes(job.status)" type="button" class="text-link" @click="selected=job;reason=''">ลองส่งอีกครั้ง</button></td></tr></tbody></table></div><button v-if="cursor" class="button actions" :disabled="loading" @click="load(true)">โหลดงานเพิ่มเติม</button></section><form v-if="selected" class="panel" @submit.prevent="retry"><h2>ลองส่งงานเดิม · {{selected.recipient}}</h2><div class="field"><label for="mail-reason">เหตุผลที่ลองส่งอีกครั้ง</label><textarea id="mail-reason" v-model="reason" required maxlength="1000" /></div><p class="hint">หาก SMTP เคยรับอีเมลแล้วแต่ตอบกลับไม่สำเร็จ การลองใหม่อาจทำให้ผู้รับได้รับอีเมลซ้ำ</p><div class="actions"><button class="button primary" :disabled="saving">{{saving?'กำลังเข้าคิว…':'เข้าคิวส่งอีกครั้ง'}}</button><button type="button" class="button" @click="selected=null">ยกเลิก</button></div></form></template></template>
